/*
 * Standalone boundary harness for CVE-2019-14895 mwifiex country-IE guard.
 *
 * This does NOT compile the kernel module. It models the exact copy arithmetic
 * of the vulnerable and patched mwifiex_process_country_ie() bodies so the
 * guard boundary (IEEE80211_COUNTRY_STRING_LEN + MWIFIEX_MAX_TRIPLET_802_11D)
 * and the heap-write invariant can be executed deterministically.
 */
#include <stdio.h>
#include <string.h>

#define IEEE80211_COUNTRY_IE_MIN_LEN 6
#define IEEE80211_COUNTRY_STRING_LEN 3
#define MWIFIEX_MAX_TRIPLET_802_11D 83

struct ieee80211_country_ie_triplet {
	unsigned char first_channel;
	unsigned char num_channels;
	unsigned char max_power;
};

struct mwifiex_802_11d_domain_reg {
	unsigned char country_code[IEEE80211_COUNTRY_STRING_LEN];
	unsigned char no_of_triplet;
	struct ieee80211_country_ie_triplet triplet[MWIFIEX_MAX_TRIPLET_802_11D];
	unsigned char canary[16];
};

/* patched target logic (CU-001 + caller abort modeled by -EINVAL return) */
static int process_patched(unsigned char country_ie_len,
			   struct mwifiex_802_11d_domain_reg *d,
			   const unsigned char *country_ie)
{
	if (country_ie_len < IEEE80211_COUNTRY_IE_MIN_LEN)
		return 0;

	if (country_ie_len >
	    (IEEE80211_COUNTRY_STRING_LEN + MWIFIEX_MAX_TRIPLET_802_11D))
		return -22; /* -EINVAL */

	memcpy(d->country_code, &country_ie[2], 2);
	d->country_code[2] = ' ';
	country_ie_len -= IEEE80211_COUNTRY_STRING_LEN;
	d->no_of_triplet =
		country_ie_len / sizeof(struct ieee80211_country_ie_triplet);
	memcpy((unsigned char *)d->triplet,
	       &country_ie[2] + IEEE80211_COUNTRY_STRING_LEN, country_ie_len);
	return 0;
}

/* pre-fix vulnerable logic, no upper bound */
static void process_vulnerable(unsigned char country_ie_len,
			       struct mwifiex_802_11d_domain_reg *d,
			       const unsigned char *country_ie)
{
	if (country_ie_len < IEEE80211_COUNTRY_IE_MIN_LEN)
		return;

	memcpy(d->country_code, &country_ie[2], 2);
	d->country_code[2] = ' ';
	country_ie_len -= IEEE80211_COUNTRY_STRING_LEN;
	d->no_of_triplet =
		country_ie_len / sizeof(struct ieee80211_country_ie_triplet);
	memcpy((unsigned char *)d->triplet,
	       &country_ie[2] + IEEE80211_COUNTRY_STRING_LEN, country_ie_len);
}

static int canary_intact(const struct mwifiex_802_11d_domain_reg *d)
{
	int i;
	for (i = 0; i < 16; i++)
		if (d->canary[i] != 0xAA)
			return 0;
	return 1;
}

int main(void)
{
	unsigned char src[300];
	struct mwifiex_802_11d_domain_reg a, b;
	int failures = 0;

	memset(src, 0x5A, sizeof(src));
	printf("destination triplet capacity = %zu bytes\n",
	       sizeof(a.triplet));

	/* positive path: max accepted length 86 -> copies 83 bytes, fits */
	memset(&a, 0, sizeof(a));
	memset(a.canary, 0xAA, sizeof(a.canary));
	if (process_patched(86, &a, src) != 0 || !canary_intact(&a)) {
		printf("FAIL positive ie_len=86\n");
		failures++;
	} else {
		printf("PASS positive ie_len=86 accepted, no overflow\n");
	}

	/* positive path: ordinary length 60 -> copies 57 bytes */
	memset(&a, 0, sizeof(a));
	memset(a.canary, 0xAA, sizeof(a.canary));
	if (process_patched(60, &a, src) != 0 || !canary_intact(&a)) {
		printf("FAIL positive ie_len=60\n");
		failures++;
	} else {
		printf("PASS positive ie_len=60 accepted, no overflow\n");
	}

	/* negative path: first rejected length 87 */
	memset(&a, 0, sizeof(a));
	memset(a.canary, 0xAA, sizeof(a.canary));
	if (process_patched(87, &a, src) != -22 || !canary_intact(&a) ||
	    a.no_of_triplet != 0) {
		printf("FAIL negative ie_len=87\n");
		failures++;
	} else {
		printf("PASS negative ie_len=87 rejected with -EINVAL, no write\n");
	}

	/* negative path: worst case attacker length 255 */
	memset(&a, 0, sizeof(a));
	memset(a.canary, 0xAA, sizeof(a.canary));
	if (process_patched(255, &a, src) != -22 || !canary_intact(&a)) {
		printf("FAIL negative ie_len=255\n");
		failures++;
	} else {
		printf("PASS negative ie_len=255 rejected with -EINVAL, no write\n");
	}

	/* demonstrate the pre-fix bug on the same length */
	memset(&b, 0, sizeof(b));
	memset(b.canary, 0xAA, sizeof(b.canary));
	process_vulnerable(255, &b, src);
	if (canary_intact(&b)) {
		printf("INFO pre-fix ie_len=255 did not trip canary (unexpected)\n");
		failures++;
	} else {
		printf("PASS pre-fix ie_len=255 overflows triplet[] into adjacent memory\n");
	}

	printf("%s (%d failure(s))\n", failures ? "HARNESS FAILED" : "HARNESS OK",
	       failures);
	return failures ? 1 : 0;
}

