#include <stdio.h>
#include <string.h>

#define IEEE80211_COUNTRY_IE_MIN_LEN 6
#define IEEE80211_COUNTRY_STRING_LEN 3
#define MWIFIEX_MAX_TRIPLET_802_11D 83

struct ieee80211_country_ie_triplet {
	unsigned char first_channel;
	unsigned char num_channels;
	unsigned char max_power;
};

struct mwifiex_802_11d_domain_reg {
	unsigned char country_code[IEEE80211_COUNTRY_STRING_LEN];
	unsigned char no_of_triplet;
	struct ieee80211_country_ie_triplet triplet[MWIFIEX_MAX_TRIPLET_802_11D];
	unsigned char canary[16];
};

/* patched target logic (CU-001 + caller abort modeled by -EINVAL return) */
static int process_patched(unsigned char country_ie_len,
			   struct mwifiex_802_11d_domain_reg *d,
			   const unsigned char *country_ie)
{
	if (country_ie_len < IEEE80211_COUNTRY_IE_MIN_LEN)
		return 0;

	if (country_ie_len >
	    (IEEE80211_COUNTRY_STRING_LEN + MWIFIEX_MAX_TRIPLET_802_11D))
		return -22; /* -EINVAL */

	memcpy(d->country_code, &country_ie[2], 2);
	d->country_code[2] = ' ';
	country_ie_len -= IEEE80211_COUNTRY_STRING_LEN;
	d->no_of_triplet =
		country_ie_len / sizeof(struct ieee80211_country_ie_triplet);
	memcpy((unsigned char *)d->triplet,
	       &country_ie[2] + IEEE80211_COUNTRY_STRING_LEN, country_ie_len);
	return 0;
}

/* pre-fix vulnerable logic, no upper bound */
static void process_vulnerable(unsigned char country_ie_len,
			       struct mwifiex_802_11d_domain_reg *d,
			       const unsigned char *country_ie)
{
	if (country_ie_len < IEEE80211_COUNTRY_IE_MIN_LEN)
		return;

	memcpy(d->country_code, &country_ie[2], 2);
	d->country_code[2] = ' ';
	country_ie_len -= IEEE80211_COUNTRY_STRING_LEN;
	d->no_of_triplet =
		country_ie_len / sizeof(struct ieee80211_country_ie_triplet);
	memcpy((unsigned char *)d->triplet,
	       &country_ie[2] + IEEE80211_COUNTRY_STRING_LEN, country_ie_len);
}

static int canary_intact(const struct mwifiex_802_11d_domain_reg *d)
{
	int i;
	for (i = 0; i < 16; i++)
		if (d->canary[i] != 0xAA)
			return 0;
	return 1;
}

